// Recompute every derived number used in the "clinical" batch.
const ln2 = Math.log(2);
const out = {};
// --- F-18 decay ---
const T_F18 = 109.77;        // min, IAEA Live Chart (ENSDF) 109.77(5) min
function frac(tMin, half) { return Math.pow(0.5, tMin / half); }
out.f18 = {
  halfLife_min: T_F18,
  halfLives_in_11h: 660 / T_F18,
  remaining_after_11h_pct_T109_77: 100 * frac(660, T_F18),
  remaining_after_11h_pct_T110: 100 * frac(660, 110),
  remaining_pct: Object.fromEntries([1, 2, 4, 6, 9, 11, 12, 24].map(h => [h + 'h', +(100 * frac(h * 60, T_F18)).toPrecision(4)])),
  hours_to_1pct: T_F18 * Math.log2(100) / 60,
  hours_to_0_1pct: T_F18 * Math.log2(1000) / 60
};
// --- FDG effective dose ---
const k = 0.019; // mSv/MBq adult, ICRP 106 (quoted by EANM 2015) and ICRP 80 (quoted by SNM 2006)
out.fdgDose_mSv = Object.fromEntries([25, 185, 259, 300, 370, 400].map(a => [a + ' MBq', +(a * k).toFixed(3)]));
out.mCi = { '185 MBq': 185 / 37, '370 MBq': 370 / 37 };
// --- totals ---
out.total = {
  fdg_low: 185 * k, fdg_high: 370 * k,
  ct_range_EANM: [1, 20],
  total_min: 185 * k + 1, total_max: 370 * k + 20,
  unscear_survey_totals: [9.9, 12.2, 12.7, 14.1, 14.2, 14.3, 18.6],
  unscear_survey_lowdoseCT: [2.9, 5.9, 6, 6.3, 6.5, 8.2, 8.6],
  unscear_survey_pet_part: [5.3, 5.7, 5.9, 6, 6.8, 7, 7.6]
};
// check each UNSCEAR D19 row adds up (PET + CT = total)
out.d19check = [[6, 8.2, 14.2], [5.7, 8.6, 14.3], [7, 2.9, 9.9], [5.9, 6.3, 12.2], [5.3, 13.3, 18.6], [6.8, 5.9, 12.7], [7.6, 6.5, 14.1]].map(r => ({ sum: +(r[0] + r[1]).toFixed(1), stated: r[2] }));
// --- background comparison ---
const world = 2.4, usNat = 3.1, usAll = 6.2;
out.background = {
  us_natural_from_half_of_6_2: usAll / 2,
  years_world_for: Object.fromEntries([3.5, 7, 10, 14, 15, 25].map(d => [d + ' mSv', +(d / world).toFixed(1)])),
  years_us_for: Object.fromEntries([3.5, 7, 10, 14, 15, 25].map(d => [d + ' mSv', +(d / usNat).toFixed(1)]))
};
// --- glucose units ---
const MW = 180.156; // g/mol glucose -> 1 mmol/L = 18.016 mg/dL
out.glucose = { '11 mmol/L in mg/dL': 11 * MW / 10, '200 mg/dL in mmol/L': 200 * 10 / MW, '150 mg/dL in mmol/L': 150 * 10 / MW, '4 mmol/L in mg/dL': 4 * MW / 10, '7 mmol/L in mg/dL': 7 * MW / 10 };
// --- scale ---
out.scale = {
  world_nm_procedures: 40e6, pet_share: 0.17, world_pet_estimate: 40e6 * 0.17,
  us_2019: 2200800, us_share_of_world_estimate_pct: 100 * 2200800 / (40e6 * 0.17),
  us_sites_2019: 2370, us_fixed_sites: 2370 * 0.6, us_mobile_sites: 2370 * 0.4,
  us_other_than_cardio_neuro_pct_2019: 100 - 8 - 3,
  us_pet_systems_unscear: 1680, implied_us_population_millions: 1680 / 5.2
};
// --- total-body PET ---
out.explorer = { afov_cm: 194, ratio_to_26_3cm: 194 / 26.3, lowdose_25MBq_mSv: 25 * k, dose_ratio_370_over_25: 370 / 25, quadra_time_ratio: 16 / 1.63 };
// --- other tracers: half-lives (IAEA Live Chart) and fraction left after 1 h ---
const hl = { 'F-18': 109.77, 'Ga-68': 67.71, 'N-13': 9.965, 'Rb-82': 75.45 / 60, 'C-11': 20.364, 'O-15': 122.24 / 60 };
out.halfLives = Object.fromEntries(Object.entries(hl).map(([n, t]) => [n, { min: +t.toFixed(4), sec: +(t * 60).toFixed(2), pct_left_after_10min: +(100 * frac(10, t)).toPrecision(3), pct_left_after_60min: +(100 * frac(60, t)).toPrecision(3) }]));
console.log(JSON.stringify(out, null, 1));
EOF
node ../scripts/calc.js > ../scripts/calc_output.json; cat ../scripts/calc_output.json

